import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Explanation","description":"","frontmatter":{},"headers":[],"relativePath":"kit-prelude-lang/explanation/index.md","filePath":"vendored/kit-prelude-lang/explanation/index.md"}`),a={name:`kit-prelude-lang/explanation/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to “Explanation”">​</a></h1><h2 id="why-this-crate-exists" tabindex="-1">Why this crate exists <a class="header-anchor" href="#why-this-crate-exists" aria-label="Permalink to “Why this crate exists”">​</a></h2><p>ADR-0044 ends with the language being <em>data</em>, not code: a host loads a <code>Language</code> value, and lexing, parsing, transforming, typechecking and evaluation are all engines over it. This repo is that end state for the canonical kit — which is why it is a data crate with almost no Rust in it.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to “Where it sits”">​</a></h2><p>This crate belongs to the <code>engine-*</code> family. Plugins, kits and hosts reach it through the kit&#39;s operation slot, so the engine can be swapped without touching a language definition.</p><p>See the <a href="/docs/kit-prelude-lang/reference/">reference</a> for the API and the <a href="/docs/kit-prelude-lang/how-to/">how-to guides</a> for tasks.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};